import base64
import shutil
import zlib
from pathlib import Path


base = Path(__file__).resolve().parent
main = base / "app" / "main.py"
texto_actual = main.read_text(
    encoding="utf-8-sig"
).replace("\r\n", "\n")

if 'VERSION = "0.16.0"' not in texto_actual:
    raise RuntimeError(
        "Este parche necesita Ne-notoka "
        "HelioRegla 0.16.0"
    )

archivos = {'CHANGELOG.md': '',
 'app/comparaciones.py': '',
 'app/i18n.py': '',
 'app/main.py': '',
 'docs/ATAJOS.md': '',
 'docs/GUIA_DE_USO.md': ''}

for nombre, paquete in archivos.items():
    ruta = base / nombre
    ruta.parent.mkdir(parents=True, exist_ok=True)
    respaldo = ruta.with_name(
        ruta.name + ".bak_0160"
    )

    if ruta.exists() and not respaldo.exists():
        shutil.copy2(ruta, respaldo)

    contenido_archivo = zlib.decompress(
        base64.b64decode(paquete)
    )
    ruta.write_bytes(contenido_archivo)

print("Parche 0.16.1 instalado correctamente")
print("Se conservaron respaldos .bak_0160")
